using BusinessPartnerPortal.Api.Common;using BusinessPartnerPortal.Api.Data;using BusinessPartnerPortal.Api.Security;using Microsoft.EntityFrameworkCore;
namespace BusinessPartnerPortal.Api.Features.Integration;
public static class IntegrationEndpoints{public static IEndpointRouteBuilder MapIntegrationEndpoints(this IEndpointRouteBuilder app){var g=app.MapGroup("/api/v1/integration").RequireAuthorization().WithTags("Integration");g.MapGet("/status",async(CurrentUser current,AppDbContext db,CancellationToken ct)=>{await current.DemandAsync("INTEGRATION.VIEW",ct);var conn=db.Database.GetDbConnection();await conn.OpenAsync(ct);await using var cmd=conn.CreateCommand();cmd.CommandText="SELECT id,event_type,aggregate_id,status,attempt_count,last_error,created_at,next_attempt_at,processed_at FROM integration.outbox_messages ORDER BY created_at DESC LIMIT 500";var list=new List<object>();await using var rd=await cmd.ExecuteReaderAsync(ct);while(await rd.ReadAsync(ct))list.Add(new{id=rd.GetGuid(0),eventType=rd.GetString(1),aggregateId=rd.GetGuid(2),status=rd.GetString(3),attemptCount=rd.GetInt32(4),lastError=rd.IsDBNull(5)?null:rd.GetString(5),createdAt=rd.GetFieldValue<DateTimeOffset>(6),nextAttemptAt=rd.IsDBNull(7)?(DateTimeOffset?)null:rd.GetFieldValue<DateTimeOffset>(7),processedAt=rd.IsDBNull(8)?(DateTimeOffset?)null:rd.GetFieldValue<DateTimeOffset>(8)});return Results.Ok(list);});g.MapPost("/{id:guid}/retry",async(Guid id,CurrentUser current,AppDbContext db,CancellationToken ct)=>{await current.DemandAsync("INTEGRATION.RETRY",ct);await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE integration.outbox_messages SET status='PENDING', next_attempt_at=now(), last_error=NULL WHERE id={id}",ct);return Results.Ok(new{retried=true,id});});return app;}}
